// Platform-provided database client — do NOT edit this file manually.
// It is auto-managed by the AlgorithmShift platform.
//
// Database Settings (in .env.local):
//   ENABLE_DATABASE=true|false  - Toggle database on/off
//   DATABASE_URL=postgresql://... - Connection string (required when enabled)
//   DATABASE_SCHEMA=public      - Postgres schema (search_path); optional when
//                                 already baked into DATABASE_URL options
//
// This is the ONLY database access path in an API service. Route files import
// `query` / `pool` from here; nothing else opens a connection. On Lambda the
// pool is created once per warm container (module scope) — put a connection
// pooler (RDS Proxy, Neon/Supabase pooler) in front of the database.
import { Pool, types } from "pg";
import { env } from "./env";
import { query as mockQuery } from "./json";

// pg returns DATE/TIMESTAMP/TIMESTAMPTZ columns as JS Date objects, but every
// generated Row type declares them as strings and clients render them as-is.
// Return the raw postgres text instead; code that needs a Date can still
// construct one with new Date(value).
types.setTypeParser(1082, (v) => v); // DATE
types.setTypeParser(1114, (v) => v); // TIMESTAMP
types.setTypeParser(1184, (v) => v); // TIMESTAMPTZ

const SAFE_SCHEMA = /^[A-Za-z_][A-Za-z0-9_-]{0,62}$/;

/** Resolve tenant schema from DATABASE_SCHEMA or DATABASE_URL options. */
function resolveDatabaseSchema(databaseUrl: string): string | null {
  const fromEnv = env.DATABASE_SCHEMA.trim();
  if (fromEnv && SAFE_SCHEMA.test(fromEnv)) return fromEnv;
  try {
    const u = new URL(databaseUrl);
    const options = u.searchParams.get("options") || "";
    const match = options.match(
      /search_path\s*=\s*"?([A-Za-z_][A-Za-z0-9_-]{0,62})"?/i,
    );
    if (match?.[1]) return match[1];
  } catch {
    // ignore malformed URL
  }
  return null;
}

const isDbEnabled = env.ENABLE_DATABASE;
const hasDbUrl = env.DATABASE_URL.length > 0;

// Determine if we should use the real database or mock data
export const isMockMode = !isDbEnabled || !hasDbUrl;

const databaseSchema = !isMockMode
  ? resolveDatabaseSchema(env.DATABASE_URL)
  : null;

// Only create pool if database is enabled and URL is provided
let _pool: Pool | null = null;
if (!isMockMode) {
  _pool = new Pool({
    connectionString: env.DATABASE_URL,
    // Pin search_path at connection start so unqualified SQL (and pool.query)
    // hits the mapped schema even when a pooler strips URL options.
    ...(databaseSchema
      ? { options: `-c search_path=${databaseSchema}` }
      : {}),
    // Detect any TLS-requested URL (new `no-verify`, legacy `require`,
    // or `verify-*` variants) and always pair with `rejectUnauthorized:
    // false`. This is a platform-managed client so matching the portable
    // "trust any cert" RDS convention is the right default.
    ssl: /sslmode=(require|no-verify|verify-ca|verify-full|prefer)/i.test(
      env.DATABASE_URL,
    )
      ? { rejectUnauthorized: false }
      : false,
  });
}

/**
 * Execute a parameterised SQL query and return rows.
 *
 * When the database is disabled, falls back to mock data from src/json.ts.
 *
 * @example
 *   const rows = await query<{ id: string; name: string }>(
 *     'SELECT * FROM users WHERE active = $1', [true]
 *   );
 */
export async function query<T = Record<string, unknown>>(
  sql: string,
  params?: unknown[],
): Promise<T[]> {
  if (isMockMode) {
    return mockQuery<T>(sql, params);
  }
  if (!_pool) {
    throw new Error(
      "Database pool not initialized. Check ENABLE_DATABASE and DATABASE_URL settings.",
    );
  }
  const client = await _pool.connect();
  try {
    const result = await client.query(sql, params);
    return result.rows as T[];
  } finally {
    client.release();
  }
}

/**
 * Non-null pool export. Real-DB mode: the pg Pool. Mock mode: a shim whose
 * query() delegates to src/json.ts (rows wrapped in { rows } to match pg's
 * QueryResult shape) so route code written against pool.query works without
 * a database; other pool methods throw with a clear message.
 */
const _mockPoolShim = {
  query: async (sql: string, params?: unknown[]) => {
    const rows = await mockQuery(sql, params);
    return { rows, rowCount: rows.length, command: "", oid: 0, fields: [] };
  },
  connect: async () => {
    throw new Error(
      "No database configured (mock mode) — pool.connect() is unavailable. Use pool.query() or query().",
    );
  },
  end: async () => undefined,
} as unknown as Pool;

export const pool: Pool = _pool ?? _mockPoolShim;

/** Close the pool (graceful shutdown). No-op in mock mode. */
export async function closePool(): Promise<void> {
  if (_pool) {
    await _pool.end();
    _pool = null;
  }
}

console.log(
  `[db] Mode: ${isMockMode ? "MOCK (using src/json.ts)" : "REAL (PostgreSQL)"}` +
    (!isMockMode && databaseSchema ? ` schema=${databaseSchema}` : ""),
);
if (isMockMode && isDbEnabled && !hasDbUrl) {
  console.warn("[db] ENABLE_DATABASE=true but DATABASE_URL is missing!");
}
